package com.example.svc;

import java.util.List;

public final class OrderService {
    private final OrderRepository repository;

    public OrderService(OrderRepository repository) {
        this.repository = repository;
    }

    public List<Order> findOpen(String customerId) {
        return repository.findByCustomerAndStatus(customerId, Status.OPEN);
    }
}

class OrderServiceTest {
    @Test
    void findsOnlyOpenOrders() {
        var repo = new InMemoryOrderRepository();
        var service = new OrderService(repo);
        var open = service.findOpen("c-1");
        assertEquals(1, open.size());
        assertEquals(Status.OPEN, open.get(0).status());
    }
}

def retry(fn, attempts=3, backoff=0.2):
    for i in range(attempts):
        try:
            return fn()
        except TransientError:
            time.sleep(backoff * (2 ** i))
    raise RuntimeError('retries exhausted')

