export async function findOpenOrders(id: string): Promise<Order[]> {
  const res = await fetch(`${base}/orders?customer=${id}&status=OPEN`);
  if (!res.ok) throw new Error(`orders fetch failed: ${res.status}`);
  return res.json();
}

pub fn total_cents(orders: &[Order]) -> i64 {
    orders.iter().map(|o| o.total_cents).sum()
}

